demo_in_revH = [row[::-1] for row in demo_in]  # horizontal flip

out_cols = [
    [6, 9, 3, 1],  # col 0
    [9, 3, 4, 9],  # col 1
    [6, 9, 9, 4],  # col 2  
    [6, 9, 9, 1],  # col 3
]

# Find matching columns for each transformation
def find_matches(rows, name):
    matches = {}
    for co in range(4):
        target = out_cols[co]
        found = []
        for ci in range(30):
            col_vals = [rows[r][ci] for r in range(4)]
            if col_vals == target:
                found.append((ci, "direct"))
            elif col_vals == target[::-1]:
                found.append((ci, "reversed"))
        matches[co] = found
    return matches

print("Original demo_in:")
for co in range(4):
    print(f"  Col {co}: {find_matches(demo_in, 'orig')[co]}")

print("\nVerically flipped (demo_in[::-1]):")
for co in range(4):
    print(f"  Col {co}: {find_matches(demo_in_revV, 'vflip')[co]}")

print("\nHorizontally flipped:")
for co in range(4):
    print(f"  Col {co}: {find_matches(demo_in_revH, 'hflip')[co]}")

# Try 90 degree rotation (shear)
print("\n\nTry row shear - rows shifted cyclically:")
for shift in range(4):
    shifted = demo_in[shift:] + demo_in[:shift]
    print(f"Shift {shift}:")
    for co in range(4):
        found = find_matches(shifted, f's{shift}')[co]
        if found:
            print(f"  Col {co}: {found}")

